import zipfile, xml.etree.ElementTree as ET
ns = {'m': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
z = zipfile.ZipFile('budget.xlsx')
root = ET.fromstring(z.read('xl/worksheets/sheet1.xml'))
rows = []
for row in root.findall('.//m:row', ns):
    cells = {}
    for c in row.findall('m:c', ns):
        ref = c.get('r'); col = ''.join(ch for ch in ref if ch.isalpha())
        t = c.get('t', 'n')
        v = c.find('m:v', ns)
        if t == 'inlineStr':
            val = ''.join(x.text or '' for x in c.findall('.//m:t', ns))
        elif v is not None:
            val = float(v.text)
        else:
            val = None
        cells[col] = val
    if cells:
        rows.append((int(row.get('r')), cells))
expenses = [c for r, c in rows if 11 <= r <= 22]
cats = {}
for c in expenses:
    cats.setdefault(c['A'], 0)
    cats[c['A']] += c['C']
total = sum(cats.values())
print('Expenses by category:')
for k, v in cats.items():
    print(f'  {k}: \${v:,.0f}')
print(f'TOTAL EXPENSES: \${total:,.0f}')
"

